## What Problem This Solves

Fixes an issue where `openclaw doctor` could buffer an oversized Active Memory legacy `session-toggles.json` file while checking or migrating old per-session opt-outs.

## Why This Change Was Made

The Active Memory doctor migration now reads the legacy toggle source through a bounded production file reader. Valid legacy toggle files still migrate into plugin state, while oversized sources are reported and left in place for a later manual or reduced-size migration attempt.

## User Impact

Operators get a bounded, recoverable doctor migration path instead of unbounded memory growth on an oversized Active Memory legacy toggle file.

## Evidence

- Real module proof: Active Memory's production doctor migration imports 10,000 valid legacy opt-outs under the cap and rejects an oversized source without writing plugin-state rows or archiving it.
- Focused tests: Active Memory doctor migration tests cover normal import, malformed timestamp normalization, max supported valid input, and oversized source handling.

```text
$ ./node_modules/.bin/esbuild proof-live.ts --bundle --platform=node --format=esm --packages=external --alias:openclaw/plugin-sdk=./src/plugin-sdk --outfile=.proof-live.mjs && node .proof-live.mjs
valid: bytes=548904 preview=true entries=10000 warnings=0 archived=true
oversized: preview=true warnings=1 entries=0 sourceKept=true archived=false

$ node scripts/run-vitest.mjs extensions/active-memory/doctor-contract-api.test.ts
Test Files  1 passed (1)
Tests  4 passed (4)
```

<details>
<summary>proof-live.ts</summary>

```ts
import fs from "node:fs/promises";
import os from "node:os";
import path from "node:path";
import {
  createPluginStateKeyedStoreForTests,
  resetPluginStateStoreForTests,
} from "./src/plugin-sdk/plugin-state-test-runtime.ts";
import type {
  OpenKeyedStoreOptions,
  PluginDoctorStateMigrationContext,
} from "./src/plugin-sdk/runtime-doctor.ts";
import {
  LEGACY_TOGGLE_STATE_MAX_BYTES,
  stateMigrations,
} from "./extensions/active-memory/doctor-contract-api.ts";

function createDoctorContext(env: NodeJS.ProcessEnv): PluginDoctorStateMigrationContext {
  return {
    openPluginStateKeyedStore<T>(options: OpenKeyedStoreOptions) {
      return createPluginStateKeyedStoreForTests<T>("active-memory", {
        ...options,
        env: options.env ?? env,
      });
    },
  };
}

function migrationParams(stateDir: string, env: NodeJS.ProcessEnv) {
  return {
    config: {},
    env,
    stateDir,
    oauthDir: path.join(stateDir, "oauth"),
    context: createDoctorContext(env),
  };
}

function requireDefined<T>(value: T | undefined, label: string): T {
  if (value === undefined) {
    throw new Error(label);
  }
  return value;
}

async function main() {
  resetPluginStateStoreForTests();
  const tempRoot = await fs.mkdtemp(path.join(os.tmpdir(), "openclaw-active-memory-proof-"));
  try {
    const migration = requireDefined(stateMigrations[0], "active-memory state migration");

    const validStateDir = path.join(tempRoot, "valid");
    const validEnv = { ...process.env, OPENCLAW_STATE_DIR: validStateDir };
    const validSourcePath = path.join(validStateDir, "plugins", "active-memory", "session-toggles.json");
    await fs.mkdir(path.dirname(validSourcePath), { recursive: true });
    const validSessions = Object.fromEntries(
      Array.from({ length: 10_000 }, (_, index) => [
        `telegram:dm:${String(index).padStart(5, "0")}`,
        { disabled: true, updatedAt: index },
      ]),
    );
    const validPayload = JSON.stringify({ sessions: validSessions });
    await fs.writeFile(validSourcePath, validPayload);
    const validPreview = await migration.detectLegacyState(migrationParams(validStateDir, validEnv));
    const validResult = await migration.migrateLegacyState(migrationParams(validStateDir, validEnv));
    const validEntries = await createDoctorContext(validEnv)
      .openPluginStateKeyedStore({ namespace: "session-toggles", maxEntries: 10_000 })
      .entries();
    const validSourceArchived = await fs.access(`${validSourcePath}.migrated`).then(
      () => true,
      () => false,
    );
    console.log(
      `valid: bytes=${Buffer.byteLength(validPayload, "utf8")} preview=${validPreview?.preview[0]?.includes("10000 entries")} entries=${validEntries.length} warnings=${validResult.warnings.length} archived=${validSourceArchived}`,
    );

    resetPluginStateStoreForTests();
    const oversizedStateDir = path.join(tempRoot, "oversized");
    const oversizedEnv = { ...process.env, OPENCLAW_STATE_DIR: oversizedStateDir };
    const oversizedSourcePath = path.join(
      oversizedStateDir,
      "plugins",
      "active-memory",
      "session-toggles.json",
    );
    await fs.mkdir(path.dirname(oversizedSourcePath), { recursive: true });
    await fs.writeFile(oversizedSourcePath, Buffer.alloc(LEGACY_TOGGLE_STATE_MAX_BYTES + 1));
    const oversizedPreview = await migration.detectLegacyState(
      migrationParams(oversizedStateDir, oversizedEnv),
    );
    const oversizedResult = await migration.migrateLegacyState(
      migrationParams(oversizedStateDir, oversizedEnv),
    );
    const oversizedEntries = await createDoctorContext(oversizedEnv)
      .openPluginStateKeyedStore({ namespace: "session-toggles", maxEntries: 10_000 })
      .entries();
    const oversizedSourceKept = await fs.access(oversizedSourcePath).then(
      () => true,
      () => false,
    );
    const oversizedSourceArchived = await fs.access(`${oversizedSourcePath}.migrated`).then(
      () => true,
      () => false,
    );
    console.log(
      `oversized: preview=${oversizedPreview?.preview[0]?.includes(`exceeds ${LEGACY_TOGGLE_STATE_MAX_BYTES} bytes`)} warnings=${oversizedResult.warnings.length} entries=${oversizedEntries.length} sourceKept=${oversizedSourceKept} archived=${oversizedSourceArchived}`,
    );
  } finally {
    resetPluginStateStoreForTests();
    await fs.rm(tempRoot, { recursive: true, force: true });
  }
}

void main();
```

</details>

